        stages.AddRange(newStages);
    }




    for(var p=0;p< stages.Count;p++)
    {
        var stage = stages[p];
        stage.HasStages = false;

        if(myuser!=null)
        {
            var userAnswer = _context.UserAnswers.Where(a => a.ParentId == stage.Id.ToString() && a.UserId == myuser.Id.ToString()).FirstOrDefault();
