            {
                stage.UserAnswer = "";
            }

            var review = _context.Reviews.Where(a => a.StageId == stage.Id.ToString() && a.UserId == myuser.Id.ToString()).FirstOrDefault();
            if (review != null)
            {
                stage.Review = review.Review;
            }
            else
